import React, { useEffect, useState } from "react";
import "../styles/subscription.css";

function ChannelContent({ selectedChannel, token, currentUser }) {
  const [content, setContent] = useState([]);
  const [votedPolls, setVotedPolls] = useState([]);
  const [error, setError] = useState(null);

  // Завантаження статей + опитувань
  useEffect(() => {
    if (!selectedChannel) return;

    const fetchData = async () => {
      try {
        const [articlesRes, pollsRes] = await Promise.all([
          fetch(`http://127.0.0.1:8000/api/channels/${selectedChannel.id}/articles/`),
          fetch(`http://127.0.0.1:8000/api/channels/${selectedChannel.id}/polls/`),
        ]);

        if (!articlesRes.ok || !pollsRes.ok) throw new Error("Помилка при завантаженні контенту");

        const [articles, polls] = await Promise.all([articlesRes.json(), pollsRes.json()]);

        // Об’єднуємо контент і сортуємо за датою створення
        const combined = [
          ...articles.map(a => ({ ...a, type: "article" })),
          ...polls.map(p => ({ ...p, type: "poll" })),
        ].sort((a, b) => new Date(b.created_at) - new Date(a.created_at));

        setContent(combined);
      } catch (err) {
        setError(err.message);
      }
    };

    fetchData();
  }, [selectedChannel]);

  // Голосування в опитуванні
  const handleVote = async (pollId, choiceId) => {
    if (votedPolls.includes(pollId)) return; // Заборона повторного голосування

    try {
      const res = await fetch(`http://127.0.0.1:8000/api/polls/${pollId}/vote/${choiceId}/`, {
        method: "POST",
        headers: {
          "Authorization": `Bearer ${token}`,
          "Content-Type": "application/json",
        },
      });

      if (!res.ok) throw new Error("Помилка голосування");

      setVotedPolls([...votedPolls, pollId]);
      // Оновлення кількості голосів
      setContent(prev =>
        prev.map(item =>
          item.id === pollId
            ? {
                ...item,
                choices: item.choices.map(c =>
                  c.id === choiceId ? { ...c, votes: c.votes + 1 } : c
                ),
              }
            : item
        )
      );
    } catch (err) {
      console.error(err);
    }
  };

  // Видалення опитування
  const handleDeletePoll = async (pollId) => {
    try {
      const res = await fetch(`http://127.0.0.1:8000/api/polls/${pollId}/`, {
        method: "DELETE",
        headers: { "Authorization": `Bearer ${token}` },
      });

      if (!res.ok) throw new Error("Не вдалося видалити опитування");

      setContent(prev => prev.filter(item => item.id !== pollId));
    } catch (err) {
      alert(err.message);
    }
  };

  if (!selectedChannel) return <p>Оберіть канал, щоб побачити контент.</p>;
  if (error) return <p className="error">{error}</p>;

  return (
    <div className="channel-content">
      <h2>📺 {selectedChannel.name}</h2>
      {content.length === 0 && <p>Контент у цьому каналі відсутній.</p>}

      {content.map(item => (
        <div key={item.id} className={`content-card ${item.type}`}>
          {item.type === "article" ? (
            <>
              <h3>{item.title}</h3>
              {item.image && <img src={item.image} alt={item.title} />}
              <p>{item.content}</p>
            </>
          ) : (
            <div className="poll-block">
              <h3>🗳️ {item.question}</h3>

              {item.choices.map(choice => (
                <div key={choice.id} className="choice">
                  <button
                    onClick={() => handleVote(item.id, choice.id)}
                    disabled={votedPolls.includes(item.id)}
                  >
                    {choice.text}
                  </button>
                  <span className="vote-count">{choice.votes} голосів</span>
                </div>
              ))}

              {currentUser?.is_staff && (
                <button
                  className="delete-poll"
                  onClick={() => handleDeletePoll(item.id)}
                >
                  🗑️ Видалити опитування
                </button>
              )}

              {votedPolls.includes(item.id) && (
                <p className="voted-info">✅ Ви вже проголосували</p>
              )}
            </div>
          )}
        </div>
      ))}
    </div>
  );
}

export default ChannelContent;
